        for x in f:
            if x.lower().endswith('db.h'): hdrs.append(os.path.join(r,x))
print(f"ISS 宣告 header (*/inc/*db.h): {len(hdrs)}")
mod={}
for h in hdrs:
    md=os.path.dirname(os.path.dirname(h))            # 去掉 /inc/<file>
