    mod.setdefault(rel,[]).append(os.path.basename(h))
print(f"涉及模組目錄: {len(mod)}")
built={}
for rel in mod:
    p=os.path.join(BLD,rel)
    n=0
    for r,d,f in os.walk(p):
        n+=sum(1 for x in f if x.endswith('.o'))
    built[rel]=n
b=[m for m in mod if built[m]>0]; nb=[m for m in mod if built[m]==0]
hb=sum(len(mod[m]) for m in b); hnb=sum(len(mod[m]) for m in nb)
print(f"\n模組: built {len(b)} / not-built {len(nb)}")
print(f"header: built {hb} / not-built {hnb} / 合計 {hb+hnb}")
print("\n=== 目前清單 4 條的宣告模組 ===")
for want in ['ifmibdb.h','stdethdb.h','mxPortdb.h','mxRSTPdb.h','mxIgmpdb.h']:
    hit=[(m,built[m]) for m in mod if want in mod[m]]
    for m,n in hit: print(f"  {want:14s} -> {m:42s} {n:4d} .o  {'✓ built' if n else '✗ NOT built'}")
    if not hit: print(f"  {want:14s} -> (EDS 樹中無此 header)")
